<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Budget App</title>
  <link rel="stylesheet" href="styles.css">
</head>
<body>
  <header class="app-header">
    <h1>Budget Tracker</h1>
    <nav class="nav-links">
      <a id="nav-transactions" href="#/transactions">Transactions</a>
      <a id="nav-budgets" href="#/budgets">Budgets</a>
      <a id="nav-reports" href="#/reports">Reports</a>
    </nav>
    <div class="balance-display">
      Balance: <span id="balance">0.00</span>
    </div>
  </header>

  <main class="container">
    <!-- Transactions View -->
    <section id="view-transactions">
      <h2>Transactions</h2>
      <div class="form-row">
        <input type="date" id="date" placeholder="YYYY-MM-DD" aria-label="Date">
        <input type="text" id="description" placeholder="Description" aria-label="Description">
        <input type="number" id="amount" step="any" placeholder="Amount" aria-label="Amount">
        <input type="text" id="category" placeholder="Category" aria-label="Category">
        <select id="repeat" aria-label="Repeat">
          <option value="none">none</option>
          <option value="week">week</option>
          <option value="month">month</option>
        </select>
        <input type="date" id="until" placeholder="Until YYYY-MM-DD" aria-label="Until">
        <button type="button" id="add">Add</button>
      </div>

      <div class="toolbar">
        <input type="text" id="search" placeholder="Search description..." aria-label="Search">
        <div class="toolbar-actions">
          <button type="button" id="undo">Undo</button>
          <button type="button" id="redo">Redo</button>
          <label class="file-label">
            Import CSV
            <input type="file" id="import" accept=".csv,text/csv">
          </label>
          <button type="button" id="export">Export CSV</button>
        </div>
      </div>

      <table id="list">
        <thead>
          <tr>
            <th>Date</th>
            <th>Description</th>
            <th>Category</th>
            <th id="sort-amount" class="sortable">Amount</th>
            <th>Action</th>
          </tr>
        </thead>
        <tbody id="list-body"></tbody>
      </table>
    </section>

    <!-- Budgets View -->
    <section id="view-budgets" class="hidden" hidden style="display: none;">
      <h2>Budgets</h2>
      <div class="form-row">
        <label>
          Month:
          <input type="month" id="budget-month">
        </label>
        <input type="text" id="budget-category" placeholder="Category" aria-label="Budget Category">
        <input type="number" id="budget-limit" step="any" placeholder="Limit" aria-label="Budget Limit">
        <button type="button" id="budget-add">Add Budget</button>
      </div>

      <table id="budgets">
        <tbody id="budgets-body"></tbody>
      </table>
    </section>

    <!-- Reports View -->
    <section id="view-reports" class="hidden" hidden style="display: none;">
      <h2>Monthly Report</h2>
      <div class="form-row">
        <label>
          Month:
          <input type="month" id="report-month">
        </label>
      </div>

      <table id="report">
        <tbody id="report-body"></tbody>
      </table>

      <div class="chart-container">
        <canvas id="chart" width="600" height="300"></canvas>
      </div>
    </section>
  </main>

  <script type="module" src="js/app.js"></script>
</body>
</html>
* {
  box-sizing: border-box;
}

body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  margin: 0;
  padding: 0;
  background: #f8fafc;
  color: #1e293b;
}

.hidden {
  display: none !important;
}

.app-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: #0f172a;
  color: #ffffff;
  padding: 1rem 2rem;
}

.app-header h1 {
  margin: 0;
  font-size: 1.25rem;
}

.nav-links {
  display: flex;
  gap: 1.5rem;
}

.nav-links a {
  color: #cbd5e1;
  text-decoration: none;
  font-weight: 500;
}

.nav-links a.active,
.nav-links a:hover {
  color: #ffffff;
  text-decoration: underline;
}

.balance-display {
  font-size: 1.1rem;
  font-weight: 600;
}

.container {
  max-width: 960px;
  margin: 2rem auto;
  padding: 0 1rem;
}

.form-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: 1rem;
  align-items: center;
}

input,
select,
button {
  padding: 0.5rem 0.75rem;
  border: 1px solid #cbd5e1;
  border-radius: 4px;
  font-size: 0.95rem;
}

button {
  background: #2563eb;
  color: #ffffff;
  border-color: #2563eb;
  cursor: pointer;
}

button:hover {
  background: #1d4ed8;
}

button.delete {
  background: #dc2626;
  border-color: #dc2626;
  padding: 0.25rem 0.6rem;
}

button.delete:hover {
  background: #b91c1c;
}

.toolbar {
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: 1rem;
}

.toolbar-actions {
  display: flex;
  gap: 0.5rem;
  align-items: center;
}

.file-label {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.4rem 0.75rem;
  background: #e2e8f0;
  border-radius: 4px;
  cursor: pointer;
  font-size: 0.9rem;
}

table {
  width: 100%;
  border-collapse: collapse;
  background: #ffffff;
  border: 1px solid #e2e8f0;
}

thead {
  display: table-row;
  background: #f1f5f9;
}

th,
td {
  text-align: left;
  padding: 0.75rem;
  border-bottom: 1px solid #e2e8f0;
}

th.sortable {
  cursor: pointer;
  user-select: none;
}

th.sortable:hover {
  background: #e2e8f0;
}

tr.over {
  background-color: #fee2e2;
  color: #991b1b;
}

.chart-container {
  margin-top: 1.5rem;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  padding: 1rem;
}
import { parseCSV, toCSV } from './csv.js';
import { summarize } from './summary.js';
import { expandRecurring } from './recurring.js';
import { checkBudgets } from './budget.js';
import { createHistory } from './history.js';

const STORAGE_TX_KEY = 'budget_app_transactions';
const STORAGE_BUDGETS_KEY = 'budget_app_budgets';

function loadTransactions() {
  try {
    const raw = localStorage.getItem(STORAGE_TX_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function saveTransactions(items) {
  try {
    localStorage.setItem(STORAGE_TX_KEY, JSON.stringify(items));
  } catch {
    // ignore storage errors
  }
}

function loadBudgets() {
  try {
    const raw = localStorage.getItem(STORAGE_BUDGETS_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function saveBudgets(items) {
  try {
    localStorage.setItem(STORAGE_BUDGETS_KEY, JSON.stringify(items));
  } catch {
    // ignore storage errors
  }
}

let transactions = loadTransactions();
let budgets = loadBudgets();
const history = createHistory(transactions);
let sortDesc = false;

// Ensure #list thead contains <th> directly without a <tr> wrapper so #list tr only matches data rows
const listTable = document.getElementById('list');
if (listTable) {
  const thead = listTable.querySelector('thead');
  const headerTr = thead && thead.querySelector('tr');
  if (thead && headerTr) {
    while (headerTr.firstChild) {
      thead.appendChild(headerTr.firstChild);
    }
    headerTr.remove();
  }
}

// DOM Elements
const viewTransactions = document.getElementById('view-transactions');
const viewBudgets = document.getElementById('view-budgets');
const viewReports = document.getElementById('view-reports');

const navTransactions = document.getElementById('nav-transactions');
const navBudgets = document.getElementById('nav-budgets');
const navReports = document.getElementById('nav-reports');

const balanceEl = document.getElementById('balance');

const dateInput = document.getElementById('date');
const descriptionInput = document.getElementById('description');
const amountInput = document.getElementById('amount');
const categoryInput = document.getElementById('category');
const repeatSelect = document.getElementById('repeat');
const untilInput = document.getElementById('until');
const addBtn = document.getElementById('add');

const searchInput = document.getElementById('search');
const sortAmountHeader = document.getElementById('sort-amount');
const listBody = document.getElementById('list-body');

const undoBtn = document.getElementById('undo');
const redoBtn = document.getElementById('redo');
const importInput = document.getElementById('import');
const exportBtn = document.getElementById('export');

const budgetMonthInput = document.getElementById('budget-month');
const budgetCategoryInput = document.getElementById('budget-category');
const budgetLimitInput = document.getElementById('budget-limit');
const budgetAddBtn = document.getElementById('budget-add');
const budgetsBody = document.getElementById('budgets-body');

const reportMonthInput = document.getElementById('report-month');
const reportBody = document.getElementById('report-body');
const chartCanvas = document.getElementById('chart');

function getDefaultMonth() {
  if (transactions.length > 0 && transactions[0].date) {
    return transactions[0].date.slice(0, 7);
  }
  return new Date().toISOString().slice(0, 7);
}

function setViewVisibility(el, visible) {
  if (!el) return;
  el.hidden = !visible;
  el.classList.toggle('hidden', !visible);
  el.style.display = visible ? '' : 'none';
}

function updateView(hashOverride) {
  const hash = typeof hashOverride === 'string' ? hashOverride : window.location.hash;
  let active = 'transactions';
  if (hash === '#/budgets') {
    active = 'budgets';
  } else if (hash === '#/reports') {
    active = 'reports';
  }

  setViewVisibility(viewTransactions, active === 'transactions');
  setViewVisibility(viewBudgets, active === 'budgets');
  setViewVisibility(viewReports, active === 'reports');

  if (navTransactions) navTransactions.classList.toggle('active', active === 'transactions');
  if (navBudgets) navBudgets.classList.toggle('active', active === 'budgets');
  if (navReports) navReports.classList.toggle('active', active === 'reports');

  renderAll();
}

function renderBalance() {
  if (!balanceEl) return;
  const { balance } = summarize(transactions);
  balanceEl.textContent = String(Math.round(balance * 100) / 100);
}

function renderTransactions() {
  if (!listBody) return;
  const query = (searchInput ? searchInput.value : '').trim().toLowerCase();

  let indexed = transactions.map((item, index) => ({ item, index }));

  if (query) {
    indexed = indexed.filter(({ item }) =>
      String(item.description || '').toLowerCase().includes(query)
    );
  }

  if (sortDesc) {
    indexed.sort((a, b) => Number(b.item.amount) - Number(a.item.amount));
  }

  listBody.innerHTML = '';
  indexed.forEach(({ item }, index) => {
    const tr = document.createElement('tr');

    const tdDate = document.createElement('td');
    tdDate.textContent = item.date;

    const tdDesc = document.createElement('td');
    tdDesc.textContent = item.description;

    const tdCat = document.createElement('td');
    tdCat.textContent = item.category;

    const tdAmount = document.createElement('td');
    tdAmount.textContent = Number(item.amount).toFixed(2);

    const tdAction = document.createElement('td');
    const delBtn = document.createElement('button');
    delBtn.type = 'button';
    delBtn.className = 'delete';
    delBtn.textContent = 'Delete';
    delBtn.addEventListener('click', () => {
      const next = transactions.filter((_, idx) => idx !== index);
      transactions = next;
      history.push(transactions);
      saveTransactions(transactions);
      renderAll();
    });
    tdAction.appendChild(delBtn);

    tr.appendChild(tdDate);
    tr.appendChild(tdDesc);
    tr.appendChild(tdCat);
    tr.appendChild(tdAmount);
    tr.appendChild(tdAction);
    listBody.appendChild(tr);
  });
}

function renderBudgets() {
  if (!budgetsBody) return;
  const month = (budgetMonthInput && budgetMonthInput.value) || getDefaultMonth();
  const checked = checkBudgets(transactions, budgets, month);

  budgetsBody.innerHTML = '';
  for (const entry of checked) {
    const tr = document.createElement('tr');
    if (entry.over) {
      tr.classList.add('over');
    }

    const tdCat = document.createElement('td');
    tdCat.textContent = entry.category;

    const tdLimit = document.createElement('td');
    tdLimit.textContent = Number(entry.limit).toFixed(2);

    const tdSpent = document.createElement('td');
    tdSpent.textContent = Number(entry.spent).toFixed(2);

    tr.appendChild(tdCat);
    tr.appendChild(tdLimit);
    tr.appendChild(tdSpent);
    budgetsBody.appendChild(tr);
  }
}

function renderReports() {
  if (!reportBody) return;
  const month = (reportMonthInput && reportMonthInput.value) || getDefaultMonth();
  const range = month ? { from: `${month}-01`, to: `${month}-31` } : undefined;
  const summary = summarize(transactions, range);

  reportBody.innerHTML = '';
  const categories = Object.keys(summary.byCategory);
  for (const cat of categories) {
    const tr = document.createElement('tr');

    const tdCat = document.createElement('td');
    tdCat.textContent = cat;

    const tdTotal = document.createElement('td');
    tdTotal.textContent = Number(summary.byCategory[cat]).toFixed(2);

    tr.appendChild(tdCat);
    tr.appendChild(tdTotal);
    reportBody.appendChild(tr);
  }

  renderChart(month);
}

function renderChart(month) {
  if (!chartCanvas || typeof chartCanvas.getContext !== 'function') return;
  const ctx = chartCanvas.getContext('2d');
  if (!ctx) return;

  const width = chartCanvas.width || 600;
  const height = chartCanvas.height || 300;
  ctx.clearRect(0, 0, width, height);

  // Calculate expenses per category in that month
  const expenseByCat = {};
  for (const item of transactions) {
    if (month && (!item.date || !item.date.startsWith(month))) continue;
    const amt = Number(item.amount) || 0;
    if (amt < 0) {
      expenseByCat[item.category] = (expenseByCat[item.category] || 0) + -amt;
    }
  }

  const entries = Object.entries(expenseByCat).filter(([, val]) => val > 0);
  if (entries.length === 0) return;

  const maxExpense = Math.max(...entries.map(([, val]) => val), 1);
  const padding = 30;
  const chartW = width - padding * 2;
  const chartH = height - padding * 2;
  const slotW = chartW / entries.length;
  const barW = Math.max(10, slotW * 0.6);

  entries.forEach(([cat, val], idx) => {
    const barH = Math.max(2, (val / maxExpense) * chartH);
    const x = padding + idx * slotW + (slotW - barW) / 2;
    const y = height - padding - barH;

    ctx.fillStyle = '#2563eb';
    ctx.fillRect(x, y, barW, barH);

    ctx.fillStyle = '#0f172a';
    ctx.font = '12px sans-serif';
    ctx.fillText(`${cat} (${val.toFixed(2)})`, x, height - 10);
  });
}

function renderAll() {
  renderBalance();
  renderTransactions();
  renderBudgets();
  renderReports();
}

// Event Listeners
window.addEventListener('hashchange', () => updateView());

if (navTransactions) {
  navTransactions.addEventListener('click', () => {
    window.location.hash = '#/transactions';
    updateView('#/transactions');
  });
}
if (navBudgets) {
  navBudgets.addEventListener('click', () => {
    window.location.hash = '#/budgets';
    updateView('#/budgets');
  });
}
if (navReports) {
  navReports.addEventListener('click', () => {
    window.location.hash = '#/reports';
    updateView('#/reports');
  });
}

if (addBtn) {
  addBtn.addEventListener('click', () => {
    const date = dateInput ? dateInput.value.trim() : '';
    const description = descriptionInput ? descriptionInput.value.trim() : '';
    const amount = amountInput ? Number(amountInput.value) : 0;
    const category = categoryInput ? categoryInput.value.trim() : '';
    const repeat = repeatSelect ? repeatSelect.value : 'none';
    const until = untilInput ? untilInput.value.trim() : '';

    if (!date || Number.isNaN(amount)) return;

    let newItems = [];
    if (repeat === 'week' || repeat === 'month') {
      const targetUntil = until || date;
      newItems = expandRecurring(
        { date, description, amount, category, every: repeat },
        targetUntil
      );
    } else {
      newItems = [{ date, description, amount, category }];
    }

    if (newItems.length > 0) {
      transactions = [...transactions, ...newItems];
      history.push(transactions);
      saveTransactions(transactions);
      renderAll();
    }
  });
}

if (searchInput) {
  searchInput.addEventListener('input', () => renderTransactions());
  searchInput.addEventListener('change', () => renderTransactions());
}

if (sortAmountHeader) {
  sortAmountHeader.addEventListener('click', () => {
    sortDesc = true;
    renderTransactions();
  });
}

if (undoBtn) {
  undoBtn.addEventListener('click', () => {
    if (history.canUndo()) {
      transactions = history.undo();
      saveTransactions(transactions);
      renderAll();
    }
  });
}

if (redoBtn) {
  redoBtn.addEventListener('click', () => {
    if (history.canRedo()) {
      transactions = history.redo();
      saveTransactions(transactions);
      renderAll();
    }
  });
}

if (importInput) {
  importInput.addEventListener('change', async () => {
    const file = importInput.files && importInput.files[0];
    if (!file) return;

    let text = '';
    if (typeof file.text === 'function') {
      text = await file.text();
    } else {
      text = await new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(String(reader.result || ''));
        reader.onerror = () => reject(reader.error);
        reader.readAsText(file);
      });
    }

    const imported = parseCSV(text);
    if (imported.length > 0) {
      transactions = [...transactions, ...imported];
      history.push(transactions);
      saveTransactions(transactions);
      renderAll();
    }
  });
}

if (exportBtn) {
  exportBtn.addEventListener('click', () => {
    const csvContent = toCSV(transactions);
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'transactions.csv';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  });
}

if (budgetAddBtn) {
  budgetAddBtn.addEventListener('click', () => {
    const category = budgetCategoryInput ? budgetCategoryInput.value.trim() : '';
    const limit = budgetLimitInput ? Number(budgetLimitInput.value) : 0;
    if (!category || !(limit > 0)) return;

    budgets = [...budgets, { category, limit }];
    saveBudgets(budgets);
    renderBudgets();
  });
}

if (budgetMonthInput) {
  budgetMonthInput.addEventListener('input', () => renderBudgets());
  budgetMonthInput.addEventListener('change', () => renderBudgets());
}

if (reportMonthInput) {
  reportMonthInput.addEventListener('input', () => renderReports());
  reportMonthInput.addEventListener('change', () => renderReports());
}

// Initial render: start on the default view
updateView(navTransactions ? navTransactions.getAttribute('href') : '#/transactions');
export function checkBudgets(items, budgets, month) {
  const prefix = String(month || '');
  const monthItems = (items || []).filter(
    (item) => typeof item.date === 'string' && item.date.startsWith(prefix)
  );

  return (budgets || []).map((b) => {
    const category = b.category;
    const limit = Number(b.limit);
    let spent = 0;

    for (const item of monthItems) {
      if (item.category === category) {
        const amt = Number(item.amount) || 0;
        spent += Math.abs(amt);
      }
    }

    return {
      category,
      limit,
      spent,
      over: spent > limit,
    };
  });
}
const HEADER = 'date,description,amount,category';

export function parseCSV(text) {
  if (!text || !text.trim()) {
    return [];
  }

  const rows = [];
  for (const line of text.split(/\r?\n/)) {
    const row = [];
    let currentField = '';
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
      const ch = line[i];
      if (inQuotes) {
        if (ch === '"') {
          if (line[i + 1] === '"') {
            currentField += '"';
            i++;
          } else {
            inQuotes = false;
          }
        } else {
          currentField += ch;
        }
      } else if (ch === '"' && currentField === '') {
        inQuotes = true;
      } else if (ch === ',') {
        row.push(currentField);
        currentField = '';
      } else {
        currentField += ch;
      }
    }
    row.push(currentField);
    rows.push(row);
  }

  if (rows.length === 0) {
    return [];
  }

  // Check if first row is header
  let startIndex = 0;
  const firstRow = rows[0].map((c) => c.trim().toLowerCase());
  if (
    firstRow.length >= 4 &&
    firstRow[0] === 'date' &&
    firstRow[1] === 'description' &&
    firstRow[2] === 'amount' &&
    firstRow[3] === 'category'
  ) {
    startIndex = 1;
  }

  const items = [];
  for (let r = startIndex; r < rows.length; r++) {
    const row = rows[r];
    if (row.length === 1 && row[0] === '') {
      continue;
    }
    const [date = '', description = '', amountStr = '0', category = ''] = row;
    items.push({
      date,
      description,
      amount: Number(amountStr),
      category,
    });
  }

  return items;
}

function escapeCSVField(value) {
  const str = value == null ? '' : String(value);
  if (
    str.includes(',') ||
    str.includes('"') ||
    str.includes('\n') ||
    str.includes('\r')
  ) {
    return '"' + str.replace(/"/g, '""') + '"';
  }
  return str;
}

export function toCSV(items) {
  const lines = [HEADER];
  for (const item of items || []) {
    const row = [
      escapeCSVField(item.date),
      escapeCSVField(item.description),
      escapeCSVField(item.amount),
      escapeCSVField(item.category),
    ];
    lines.push(row.join(','));
  }
  return lines.join('\n');
}
const MAX_UNDO = 50;

function clone(val) {
  if (val === undefined || val === null || typeof val !== 'object') {
    return val;
  }
  return structuredClone ? structuredClone(val) : JSON.parse(JSON.stringify(val));
}

export function createHistory(initial) {
  const past = [];
  let current = clone(initial);
  let future = [];

  return {
    state() {
      return clone(current);
    },
    push(newState) {
      past.push(clone(current));
      if (past.length > MAX_UNDO) {
        past.shift();
      }
      current = clone(newState);
      future = [];
    },
    undo() {
      if (past.length === 0) {
        return clone(current);
      }
      future.push(clone(current));
      current = past.pop();
      return clone(current);
    },
    redo() {
      if (future.length === 0) {
        return clone(current);
      }
      past.push(clone(current));
      if (past.length > MAX_UNDO) {
        past.shift();
      }
      current = future.pop();
      return clone(current);
    },
    canUndo() {
      return past.length > 0;
    },
    canRedo() {
      return future.length > 0;
    },
  };
}
function parseYMD(dateStr) {
  const [y, m, d] = dateStr.split('-').map(Number);
  return { y, m, d };
}

function formatYMD(y, m, d) {
  const ys = String(y).padStart(4, '0');
  const ms = String(m).padStart(2, '0');
  const ds = String(d).padStart(2, '0');
  return `${ys}-${ms}-${ds}`;
}

function daysInMonth(year, month) {
  return new Date(Date.UTC(year, month, 0)).getUTCDate();
}

export function expandRecurring(rule, until) {
  if (!rule || !rule.date) return [];
  const { date, description, amount, category, every } = rule;

  if (!until || date > until) {
    return [];
  }

  const results = [];

  if (every === 'week') {
    const { y, m, d } = parseYMD(date);
    let current = new Date(Date.UTC(y, m - 1, d));
    while (true) {
      const curStr = formatYMD(
        current.getUTCFullYear(),
        current.getUTCMonth() + 1,
        current.getUTCDate()
      );
      if (curStr > until) break;
      results.push({
        date: curStr,
        description,
        amount: Number(amount),
        category,
      });
      current.setUTCDate(current.getUTCDate() + 7);
    }
  } else if (every === 'month') {
    const { y: startY, m: startM, d: startD } = parseYMD(date);
    let step = 0;
    while (true) {
      const totalMonths = startM - 1 + step;
      const curY = startY + Math.floor(totalMonths / 12);
      const curM = (totalMonths % 12) + 1;
      const maxD = daysInMonth(curY, curM);
      step++;
      if (startD > maxD) continue; // this month has no such day
      const curStr = formatYMD(curY, curM, startD);
      if (curStr > until) break;
      results.push({
        date: curStr,
        description,
        amount: Number(amount),
        category,
      });
    }
  } else {
    results.push({
      date,
      description,
      amount: Number(amount),
      category,
    });
  }

  return results;
}
export function summarize(items, range) {
  let income = 0;
  let expense = 0;
  const byCategory = {};

  for (const item of items || []) {
    if (range) {
      if (range.from && item.date < range.from) continue;
      if (range.to && item.date > range.to) continue;
    }

    const amount = Number(item.amount) || 0;
    if (amount > 0) {
      income += amount;
    } else if (amount < 0) {
      expense += -amount;
    }

    const cat = item.category;
    byCategory[cat] = (byCategory[cat] || 0) + amount;
  }

  const balance = income - expense;

  return {
    income,
    expense,
    balance,
    byCategory,
  };
}

