function renderReports() {
  if (!reportBody) return;
  const month = (reportMonthInput && reportMonthInput.value) || getDefaultMonth();
  const range = month ? { from: `${month}-01`, to: `${month}-31` } : undefined;
  const summary = summarize(transactions, range);
  const prev = month ? previousMonth(month) : '';
  const prevSummary = prev
    ? summarize(transactions, { from: `${prev}-01`, to: `${prev}-31` })
    : { byCategory: {} };

  reportBody.innerHTML = '';
  const categories = Object.keys(summary.byCategory);
  for (const cat of Object.keys(prevSummary.byCategory)) {
    if (!(cat in summary.byCategory)) categories.push(cat);
  }
  for (const cat of categories) {
    const tr = document.createElement('tr');

    const tdCat = document.createElement('td');
    tdCat.textContent = cat;

    const total = Number(summary.byCategory[cat]) || 0;
    const prevTotal = Number(prevSummary.byCategory[cat]) || 0;

