}

if (reportMonthInput) {
  reportMonthInput.addEventListener('input', () => renderReports());
  reportMonthInput.addEventListener('change', () => renderReports());
}

// Initial render: start on the default view
updateView(navTransactions ? navTransactions.getAttribute('href') : '#/transactions');

