  try {
    localStorage.setItem(STORAGE_TX_KEY, JSON.stringify(items));
  } catch {
    // ignore storage errors
  }
}

function loadBudgets() {
  try {
    const raw = localStorage.getItem(STORAGE_BUDGETS_KEY);
