function renderBalance() {
  if (!balanceEl) return;
  const { balance } = summarize(transactions);
  balanceEl.textContent = (Math.round(balance * 100) / 100).toFixed(2);
}

function setEditing(index) {
  editingIndex = index;
  if (cancelEditBtn) cancelEditBtn.classList.toggle('editing', index !== null);
  if (addBtn) addBtn.classList.toggle('editing', index !== null);
}

function startEdit(index) {
  const item = transactions[index];
  if (!item) return;
  if (dateInput) dateInput.value = item.date || '';
  if (descriptionInput) descriptionInput.value = item.description || '';
  if (amountInput) amountInput.value = String(item.amount);
  if (categoryInput) categoryInput.value = item.category || '';
  if (repeatSelect) repeatSelect.value = 'none';
  setEditing(index);
}

function cancelEdit() {
  setEditing(null);
}

function formatChange(value) {
  const rounded = Math.round(value * 100) / 100;
  if (rounded === 0) return '0.00';
  return (rounded > 0 ? '+' : '-') + Math.abs(rounded).toFixed(2);
}

function previousMonth(month) {
  const [y, m] = month.split('-').map(Number);
  const py = m === 1 ? y - 1 : y;
  const pm = m === 1 ? 12 : m - 1;
  return `${String(py).padStart(4, '0')}-${String(pm).padStart(2, '0')}`;
}

function renderTransactions() {
  if (!listBody) return;
  const query = (searchInput ? searchInput.value : '').trim().toLowerCase();

  let indexed = transactions.map((item, index) => ({ item, index }));

  if (query) {
    indexed = indexed.filter(({ item }) =>
      String(item.description || '').toLowerCase().includes(query)
    );
  }

  if (sortDesc) {
    indexed.sort((a, b) => Number(b.item.amount) - Number(a.item.amount));
  }

  listBody.innerHTML = '';
  indexed.forEach(({ item, index }) => {
    const tr = document.createElement('tr');

    const tdDate = document.createElement('td');
    tdDate.textContent = item.date;

    const tdDesc = document.createElement('td');
    tdDesc.textContent = item.description;

    const tdCat = document.createElement('td');
    tdCat.textContent = item.category;

    const tdAmount = document.createElement('td');
    tdAmount.textContent = Number(item.amount).toFixed(2);

    const tdAction = document.createElement('td');
    const editBtn = document.createElement('button');
    editBtn.type = 'button';
    editBtn.className = 'edit';
    editBtn.textContent = 'Edit';
    editBtn.addEventListener('click', () => startEdit(index));
    tdAction.appendChild(editBtn);

    const delBtn = document.createElement('button');
    delBtn.type = 'button';
    delBtn.className = 'delete';
    delBtn.textContent = 'Delete';
